CREATE DATABASE IF NOT EXISTS wx_community DEFAULT CHARACTER SET utf8mb4;
USE wx_community;
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, openid VARCHAR(64) NOT NULL UNIQUE, nickname VARCHAR(80), avatar_url VARCHAR(500), phone VARCHAR(30), points INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activities (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(200) NOT NULL, cover_url VARCHAR(500), description TEXT, start_time DATETIME, end_time DATETIME, points INT NOT NULL DEFAULT 0, latitude DECIMAL(10,7), longitude DECIMAL(10,7), status VARCHAR(20) DEFAULT 'DRAFT', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(200) NOT NULL, cover_url VARCHAR(500), description TEXT, points_cost INT NOT NULL, stock INT NOT NULL DEFAULT 0, locked_stock INT NOT NULL DEFAULT 0, status VARCHAR(20) DEFAULT 'OFFLINE');
CREATE TABLE IF NOT EXISTS point_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, amount INT NOT NULL, balance INT NOT NULL, type VARCHAR(40), remark VARCHAR(200), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_no VARCHAR(40) NOT NULL UNIQUE, user_id BIGINT NOT NULL, product_id BIGINT NOT NULL, points INT NOT NULL, status VARCHAR(20) DEFAULT 'PENDING', expire_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daily_checkins (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, check_date DATE NOT NULL, points INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_daily_user_date(user_id,check_date));
CREATE TABLE IF NOT EXISTS admins (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
